// Safely parse the AI response and compute the kickoff call slot.
// If the AI returns garbage, professional fallbacks kick in - the client NEVER gets a broken email.
const settings = $('Workflow Settings').first().json;
const form = $('New Client Form').first().json;
const resp = $input.first().json;

let ai = {};
let aiParseFailed = false;
try {
  let raw = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
  raw = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  ai = JSON.parse(raw);
} catch (e) {
  aiParseFailed = true;
}

const clientName = (form['Client Name'] || '').trim() || 'there';
const clientEmail = (form['Client Email'] || '').trim();
const company = (form['Company Name'] || '').trim();
const pkg = (form['Package / Services Purchased'] || '').trim();
const notes = (form['Anything we should know?'] || '').trim();

// --- Kickoff slot: use the preferred date if it is valid, future and a weekday; else 3 business days out at 10:00 ---
function addBusinessDays(from, days) {
  const d = new Date(from);
  let added = 0;
  while (added < days) {
    d.setDate(d.getDate() + 1);
    const dow = d.getDay();
    if (dow !== 0 && dow !== 6) added++;
  }
  return d;
}

let start = null;
const preferred = form['Preferred Kickoff Date'];
if (preferred) {
  const p = new Date(String(preferred).slice(0, 10) + 'T10:00:00');
  if (!isNaN(p.getTime()) && p.getTime() > Date.now() && p.getDay() !== 0 && p.getDay() !== 6) {
    start = p;
  }
}
if (!start) {
  start = addBusinessDays(new Date(), 3);
  start.setHours(10, 0, 0, 0);
}
const durationMin = parseInt(settings.kickoff_duration_minutes, 10) || 45;
const end = new Date(start.getTime() + durationMin * 60000);

// --- Fallback copy (used only if the AI call failed or returned invalid JSON) ---
const emailSubject = String(ai.email_subject || ('Welcome to ' + settings.agency_name + ', ' + clientName));
const emailBodyHtml = String(ai.email_body_html || (
  '<p>Hi ' + clientName + ',</p>' +
  '<p>Welcome aboard - we are excited to get started' + (pkg ? ' on your <strong>' + pkg + '</strong>' : '') + '.</p>' +
  '<p>A calendar invite for your kickoff call is on its way. Reply to this email any time with questions.</p>' +
  '<p>' + settings.sender_name + '<br>' + settings.agency_name + '</p>'
));

const defaultTalkingPoints = [
  'Introductions and how we work together',
  'Goals and success metrics for the first 90 days',
  'Access, logins and assets we need from you',
  'Communication cadence and the first deliverable'
];
const talkingPoints = (Array.isArray(ai.kickoff_talking_points) && ai.kickoff_talking_points.length)
  ? ai.kickoff_talking_points.map(String)
  : defaultTalkingPoints;

const defaultNextSteps = [
  'Confirm signed contract and first invoice',
  'Create the client folder and project board',
  'Request logins, brand assets and access',
  'Assign the account lead and brief the team',
  'Prepare the kickoff agenda and materials'
];
const nextSteps = (Array.isArray(ai.internal_next_steps) && ai.internal_next_steps.length)
  ? ai.internal_next_steps.map(String)
  : defaultNextSteps;

return [{
  json: {
    client_name: clientName,
    client_email: clientEmail,
    company: company,
    package: pkg,
    notes: notes,
    owner_email: settings.owner_email,
    agency_name: settings.agency_name,
    sender_name: settings.sender_name,
    email_subject: emailSubject,
    email_body_html: emailBodyHtml,
    kickoff_start: start.toISOString(),
    kickoff_end: end.toISOString(),
    kickoff_talking_points: talkingPoints,
    kickoff_agenda_text: 'Kickoff call agenda:\n- ' + talkingPoints.join('\n- '),
    kickoff_talking_points_html: talkingPoints.map(s => '<li>' + s + '</li>').join(''),
    internal_next_steps: nextSteps,
    internal_next_steps_html: nextSteps.map(s => '<li>' + s + '</li>').join(''),
    ai_parse_failed: aiParseFailed
  }
}];
